```javascript
const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
if (data.length === 0) process.exit(0);

const n = parseInt(data[0], 10);
const freq = new Map();

for (let i = 1; i <= n; i++) {
    const s = data[i];
    freq.set(s, (freq.get(s) || 0) + 1);
}

let answer = 0;

for (const [s, count] of freq) {
    const substrings = new Set();
    const len = s.length;

    for (let i = 0; i < len; i++) {
        for (let j = i + 1; j <= len; j++) {
            substrings.add(s.slice(i, j));
        }
    }

    let total = 0;
    for (const sub of substrings) {
        total += freq.get(sub) || 0;
    }

    answer += count * (total - 1);
}

console.log(answer);
